// Corpus is generated by the unmodified upstream quantize_row_*_ref functions.
// File: uint32 case_count; per case: uint32 type,n,bytes; float input[n]; uint8 expected[bytes].
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <HAP_vtcm_mgr.h>
#include <qurt_hvx.h>
#include "kv-cache-quant.h"

int main(void) {
    if (qurt_hvx_lock(QURT_HVX_MODE_128B) != 0) return 2;
    uint8_t * base = HAP_request_VTCM(256*1024, 1);
    if (!base) return 3;
    FILE * f = fopen("kv-write-golden.bin", "rb");
    if (!f) return 4;
    uint32_t count;
    if (fread(&count,4,1,f)!=1) return 5;
    for (uint32_t i=0;i<count;++i) {
        uint32_t hdr[3];
        if (fread(hdr,4,3,f)!=3 || hdr[1]>8192 || hdr[2]>16384) return 6;
        float * src=(void *)base;
        uint8_t * got=base+64*1024, * ref=base+128*1024;
        if (fread(src,4,hdr[1],f)!=hdr[1] || fread(ref,1,hdr[2],f)!=hdr[2]) return 7;
        memset(got,0x55,hdr[2]+128);
        kv_quantize_row(got,src,hdr[1],hdr[0]);
        bool different = false;
        for (uint32_t j=0;j<hdr[2];++j) if (got[j]!=ref[j]) {
            // Upstream leaves IQ4_NL's code scratch unset for all-zero blocks.
            // With d=0 every code decodes to zero; our writer canonicalizes these
            // bytes. Also ignore code choices when a tiny scale rounds to zero.
            if (hdr[0] == HTP_TYPE_IQ4_NL && j % 18 >= 2) {
                uint16_t scale;
                memcpy(&scale, ref + (j / 18) * 18, 2);
                if (!(scale & 0x7fff)) continue;
            }
            different = true;
                printf("FAIL case=%u type=%u n=%u offset=%u ref=%02x got=%02x\n",(unsigned)i,(unsigned)hdr[0],(unsigned)hdr[1],(unsigned)j,ref[j],got[j]); break;
        }
        if (different) {
            return 1;
        }
        for (uint32_t j=0;j<128;++j) if (got[hdr[2]+j]!=0x55) return 8;
    }
    if (fgetc(f)!=EOF) return 9;
    fclose(f); HAP_release_VTCM(base); qurt_hvx_unlock();
    printf("PASS %u reference cache-write cases, bit exact except IQ4 zero-scale codes, guards intact\n",(unsigned)count);
    return 0;
}
